// ---------------------------------------------------------------------------
// ELEKTRİKLİ MENZİL
// Elektrikli ve hibrit araçlar için "menzil" bilgisi otomatik oluşturulur.
// Bir araca özel metin yazmak isterseniz specs içine menzil: '...' ekleyin.
// Not: Her hibrit elektrikle uzun mesafe gidemez; hibrit türüne göre açıklama değişir.
// ---------------------------------------------------------------------------
const STELLANTIS_48V = ['Peugeot', 'Opel', 'Citroën', 'Fiat', 'Alfa Romeo', 'DS'];

function electricRange(car) {
  const motor = car.specs?.motor || '';
  const km = (motor.match(/(\d[\d.]*)\s?km/) || [])[1];
  switch (car.fuel) {
    case 'Elektrik':
      return km ? `~${km} km (WLTP katalog değeri; gerçek kullanımda genellikle %15–25 daha az)` : null;
    case 'Şarj edilebilir hibrit':
      return km
        ? `~${km} km yalnızca elektrikle (WLTP); batarya bitince benzinli motorla hibrit olarak devam eder`
        : 'Bataryası şarj edilebilir; kısa mesafeleri yalnızca elektrikle gidebilir';
    case 'Hibrit':
      if (/seri hibrit|e-POWER/i.test(motor)) {
        return 'Tekerlekleri her zaman elektrik motoru döndürür, ancak dışarıdan şarj edilmez; elektriği benzinli motor üretir. Bağımsız bir elektrikli menzili yoktur.';
      }
      return 'Dışarıdan şarj edilmez. Düşük hızlarda ve kısa mesafelerde (genellikle 1–2 km) yalnızca elektrikle ilerleyebilir; elektrik motorunun asıl görevi tüketimi düşürmektir.';
    case 'Hafif hibrit':
      if (car.make === 'Subaru') {
        return 'Dışarıdan şarj edilmez. Çok düşük hızlarda birkaç yüz metre yalnızca elektrikle ilerleyebilir; anlamlı bir elektrikli menzili yoktur.';
      }
      if (STELLANTIS_48V.includes(car.make) && /1\.2L/.test(motor)) {
        return 'Dışarıdan şarj edilmez. 48V sistem park manevralarında ve yavaş trafikte kısa süreliğine yalnızca elektrikle ilerleyebilir; anlamlı bir elektrikli menzili yoktur.';
      }
      return 'Yalnızca elektrikle sürülemez. Elektrik motoru kalkışta ve hızlanmada benzinli motora destek verir, yavaşlarken enerji geri kazanır; elektrikli menzili yoktur.';
    default:
      return null;
  }
}

// ---------------------------------------------------------------------------
// ÇEKİŞ ve GÜÇ/AĞIRLIK
// ---------------------------------------------------------------------------
export const DRIVE_LABELS = {
  fwd: 'Önden çekiş (FWD)',
  rwd: 'Arkadan itiş (RWD)',
  awd: 'Sürekli dört çeker (AWD)',
  '4wd': 'Dört çeker (4WD)',
};

function driveKey(text = '') {
  if (/4WD/.test(text)) return '4wd';
  if (/AWD/.test(text)) return 'awd';
  if (/RWD/.test(text)) return 'rwd';
  if (/FWD/.test(text)) return 'fwd';
  return null;
}

// Beygir başına düşen ağırlık ve ton başına beygir
function withPowerToWeight(car, specs) {
  const kg = Number(String(specs.agirlik || '').replace(/\D/g, ''));
  if (car.hp && kg) {
    const perTon = Math.round(car.hp / (kg / 1000));
    const kgPerHp = (kg / car.hp).toFixed(1).replace('.', ',');
    return { ...specs, gucAgirlik: `${perTon} bg/ton (${kgPerHp} kg/bg)`, gucAgirlikSayi: perTon };
  }
  return specs;
}

// ---------------------------------------------------------------------------
// Otomatik alanlar: slug, genel puan ve kategori içi sıra
// ---------------------------------------------------------------------------
const withScores = RAW_CARS.map((car) => {
  const slug = car.slug || slugify(`${car.make} ${car.model} ${car.year}`);
  return {
    ...car,
    used: !!car.used,
    price: car.price ?? null,
    slug,
    wiki: WIKI_FIX[slug] ?? car.wiki ?? WIKI_TITLES[slug],
    wikiFile: car.wikiFile ?? WIKI_FILES[slug],
    specs: withPowerToWeight(car, { ...EXTRA_SPECS[slug], ...car.specs, menzil: car.specs?.menzil ?? electricRange(car) }),
    drive: driveKey(EXTRA_SPECS[slug]?.cekis ?? car.specs?.cekis),
    score: overallScore(car.ratings),
  };
});

// Eşit genel puanda, yuvarlanmamış ağırlıklı ortalaması yüksek olan öne geçer.
const exactTotal = (c) => weightedAverage(c.ratings);

// Gizli araçlar (hiddenCars.js) sitede yayınlanmaz; sıralamalar yalnızca görünen araçlarla hesaplanır
const HIDDEN = new Set(HIDDEN_SLUGS);
const visibleCars = withScores.filter((c) => !HIDDEN.has(c.slug));
export const HIDDEN_CARS = withScores.filter((c) => HIDDEN.has(c.slug)).map(({ slug, category }) => ({ slug, category }));

const rankMap = new Map();
for (const cat of CATEGORIES) {
  visibleCars
    .filter((c) => c.category === cat.slug)
    .sort((a, b) => b.score - a.score || exactTotal(b) - exactTotal(a))
    .forEach((c, i) => rankMap.set(c.slug, i + 1));
}

export const CARS = visibleCars.map((c) => ({ ...c, rank: rankMap.get(c.slug) }));

export function getCategory(slug) {
  return CATEGORIES.find((c) => c.slug === slug);
}

export function getCar(slug) {
  return CARS.find((c) => c.slug === slug);
}

export function carsInCategory(slug) {
  return CARS.filter((c) => c.category === slug).sort((a, b) => a.rank - b.rank);
}

export function searchCars(query) {
  const q = query.trim().toLocaleLowerCase('tr-TR');
  if (!q) return [];
  return CARS.filter((c) =>
    `${c.make} ${c.model} ${c.version} ${c.year}`.toLocaleLowerCase('tr-TR').includes(q)
  ).sort((a, b) => b.score - a.score);
}
